export interface DirectoryEntry {
  id: string;
  label: string;
  keywords: string[];
}

function copyEntry(entry: DirectoryEntry): DirectoryEntry {
  return { id: entry.id, label: entry.label, keywords: [...entry.keywords] };
}

export class DirectoryIndex {
  private readonly entries: DirectoryEntry[];
  private readonly byId = new Map<string, DirectoryEntry>();

  constructor(entries: readonly DirectoryEntry[]) {
    if (!Array.isArray(entries)) throw new TypeError("entries must be an array");
    this.entries = [];
    for (const entry of entries) {
      if (typeof entry !== "object" || entry === null ||
          typeof entry.id !== "string" || entry.id.trim() === "" ||
          typeof entry.label !== "string" || entry.label.trim() === "" ||
          !Array.isArray(entry.keywords) ||
          entry.keywords.some((word: unknown) => typeof word !== "string")) {
        throw new TypeError("malformed entry");
      }
      if (this.byId.has(entry.id)) throw new TypeError("duplicate id");
      const copied: DirectoryEntry = {
        id: entry.id,
        label: entry.label,
        keywords: [...entry.keywords],
      };
      this.entries.push(copied);
      this.byId.set(copied.id, copied);
    }
  }

  get(id: string): DirectoryEntry | null {
    if (typeof id !== "string") throw new TypeError("id must be a string");
    const entry = this.byId.get(id);
    return entry === undefined ? null : copyEntry(entry);
  }

  search(text: string, limit: number): DirectoryEntry[] {
    if (typeof text !== "string") throw new TypeError("text must be a string");
    if (!Number.isSafeInteger(limit) || limit < 0) {
      throw new TypeError("invalid limit");
    }
    const normalized = text.trim();
    const tokens = normalized === "" ? [] : normalized.split(/\s+/);
    return this.entries
      .filter((entry) => {
        const haystack = `${entry.label} ${entry.keywords.join(" ")}`.toLowerCase();
        return tokens.every((token) => haystack.includes(token));
      })
      .slice()
      .sort((a, b) =>
        a.label < b.label ? -1 :
        a.label > b.label ? 1 :
        a.id < b.id ? -1 :
        a.id > b.id ? 1 : 0)
      .slice(0, limit)
      .map(copyEntry);
  }
}

