import { DirectoryIndex } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), `${message}: ${JSON.stringify(actual)}`);
}
function throwsTypeError(action: () => void, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof TypeError, message);
}

const keywords = ['Red Fruit', 'food'];
const entries = [
  { id: 'z', label: 'apple', keywords },
  { id: 'a', label: 'Banana', keywords: ['yellow fruit'] },
  { id: 'b', label: 'apple', keywords: ['green'] },
];
const index = new DirectoryIndex(entries);
keywords[0] = 'changed';
entries[0].label = 'changed';
equal(index.get('z'), { id: 'z', label: 'apple', keywords: ['Red Fruit', 'food'] }, 'constructor copies input');
assert(index.get('missing') === null, 'missing ID');

const first = index.get('z')!;
const second = index.get('z')!;
assert(first !== second && first.keywords !== second.keywords, 'get returns fresh copies');
first.label = 'mutated';
first.keywords.push('mutated');
assert(index.get('z')!.label === 'apple' && index.get('z')!.keywords.length === 2, 'get result isolated');

equal(index.search('', 10).map((entry) => entry.id), ['a', 'b', 'z'], 'empty query and code-unit sorting');
equal(index.search('  FRUIT   red ', 10).map((entry) => entry.id), ['z'], 'all normalized tokens required');
equal(index.search('apple', 1).map((entry) => entry.id), ['b'], 'label match, tie sort, and limit');
assert(index.search('anything', 0).length === 0, 'zero limit');
const results = index.search('fruit', 10);
const later = index.search('fruit', 10);
assert(results !== later && results[0] !== later[0] && results[0].keywords !== later[0].keywords, 'search copies results');

throwsTypeError(() => new DirectoryIndex(null as any), 'entries array required');
throwsTypeError(() => new DirectoryIndex([{ id: ' ', label: 'x', keywords: [] }]), 'blank ID rejected');
throwsTypeError(() => new DirectoryIndex([{ id: 'x', label: ' ', keywords: [] }]), 'blank label rejected');
throwsTypeError(() => new DirectoryIndex([{ id: 'x', label: 'x', keywords: [2] as any }]), 'malformed keyword rejected');
throwsTypeError(() => new DirectoryIndex([{ id: 'x', label: 'x', keywords: [] }, { id: 'x', label: 'y', keywords: [] }]), 'duplicate ID rejected');
for (const limit of [-1, 1.5, Number.MAX_SAFE_INTEGER + 1]) {
  throwsTypeError(() => index.search('', limit), 'invalid limit rejected');
}

